INSERT INTO PRJ_PRJCT_COMP_ORG_BSC_INFO_TBL (
	COMP_SEQ
  , 	COMP_CD
  , USE_YN
  , COMP_ORG_NM
  , COMP_NM
  , COMP_ORG_DESC
  , RGST_DT
  , RGST_SEQ
  , RGST_NM
)
VALUES (
	#{compSeq, jdbcType=NUMERIC}
  , 	#{compCd, jdbcType=VARCHAR}
  , (
		CASE
			WHEN (#{useYn, jdbcType=VARCHAR} IS NULL OR #{useYn, jdbcType=VARCHAR} = '') THEN 'Y'
			ELSE   #{useYn, jdbcType=VARCHAR}
		END
   )
  ,  #{compOrgNm, jdbcType=VARCHAR}
  ,  #{compNm, jdbcType=VARCHAR}
  ,  #{compOrgDesc, jdbcType=VARCHAR}
  , CURRENT_TIMESTAMP(3)
  , #{rgstSeq, jdbcType=NUMERIC}
  , #{rgstNm, jdbcType=VARCHAR}
)

mapper.update:
UPDATE PRJ_PRJCT_COMP_ORG_BSC_INFO_TBL
SET 		USE_YN 		= 	(
					CASE
						WHEN (#{useYn, jdbcType=VARCHAR} IS NULL OR #{useYn, jdbcType=VARCHAR} = '') THEN USE_YN
						ELSE   #{useYn, jdbcType=VARCHAR}
					END
		    )
		  , COMP_ORG_NM 	=	(
					CASE
						WHEN (#{compOrgNm, jdbcType=VARCHAR} IS NULL OR #{compOrgNm, jdbcType=VARCHAR} = '') THEN COMP_ORG_NM
						ELSE   #{compOrgNm, jdbcType=VARCHAR}
					END
		    )
		  , COMP_ORG_DESC 	= 	(
					CASE
						WHEN (#{compOrgDesc, jdbcType=VARCHAR} IS NULL OR #{compOrgDesc, jdbcType=VARCHAR} = '') THEN COMP_ORG_DESC
						ELSE   #{compOrgDesc, jdbcType=VARCHAR}
					END
		    )
		  , UPDT_DT 	= 	CURRENT_TIMESTAMP(3)
		  , UPDT_SEQ 	=	#{deltSeq, jdbcType=NUMERIC}	
		  , UPDT_NM 	= 	#{deltNm, jdbcType=VARCHAR}
WHERE 	1 	= 	1
AND 		DELT_YN = 'N'
AND 		(((#{compOrgSeq, jdbcType=NUMERIC} IS NULL) OR (#{compOrgSeq, jdbcType=NUMERIC} = 0)) OR (COMP_ORG_SEQ = #{compOrgSeq, jdbcType=NUMERIC}))

