	PRJCT_SEQ
  , COMP_ORG_SEQ
  , COMP_SEQ
  , USE_YN
  , PRJCT_CD
  , COMP_CD
  , PRJCT_NM
  , COMP_NM
  , RGST_DT	
  , RGST_SEQ
  , RGST_NM
)
VALUES (
	#{prjctSeq, jdbcType=NUMERIC}
  , 	#{compOrgSeq, jdbcType=NUMERIC}
  , #{compSeq, jdbcType=NUMERIC}
  , (
		CASE
			WHEN (#{useYn, jdbcType=VARCHAR} IS NULL OR #{useYn, jdbcType=VARCHAR} = '') THEN 'Y'
			ELSE    #{useYn, jdbcType=VARCHAR}
		END	
    )
   , #{prjctCd, jdbcType=VARCHAR}
   , #{compCd, jdbcType=VARCHAR}
   , #{prjctNm, jdbcType=VARCHAR} 
   , #{compNm, jdbcType=VARCHAR}
   , CURRENT_TIMESTAMP(3)
   , #{rgstSeq, jdbcType=NUMERIC}
   , #{rgstNm, jdbcType=VARCHAR}
)

